import re,os
root='AlgebraicJacobian'
def path(mod):
    return mod.replace('.','/')+'.lean'
def imports(f):
    out=[]
    try:
        for line in open(f):
            m=re.match(r'import\s+(AlgebraicJacobian[\w.]*)',line)
            if m: out.append(m.group(1))
            if line.startswith(('theorem','def','namespace','/-!','universe','set_option')): break
    except FileNotFoundError: pass
    return out
seen=set()
stack=['AlgebraicJacobian.RiemannRoch.ChiLedger']
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for i in imports(path(m)):
        if i not in seen: stack.append(i)
tot=0; sor=0
for m in sorted(seen):
    p=path(m)
    if os.path.exists(p):
        txt=open(p).read()
        tot+=txt.count('\n')
        sor+=len(re.findall(r'(?<![\w.])sorry(?![\w])',txt))
print('files',len(seen),'lines',tot,'sorry-tokens',sor)
for m in sorted(seen): print('  ',m)
EOF
